WITH remaining_keys AS (SELECT carrier, status FROM shipments EXCEPT DISTINCT SELECT carrier, status FROM shipments WHERE delivered_date BETWEEN '2023-06-05' AND '2024-11-17'), reconciled AS (SELECT s.* FROM shipments s INNER JOIN remaining_keys k ON s.carrier = k.carrier AND s.status = k.status) SELECT CASE WHEN cost >= 78 THEN 'PREMIUM' ELSE 'STANDARD' END AS cost_tier, DATE_TRUNC('YEAR', delivered_date) AS year_start, PERCENTILE_APPROX(cost, ARRAY(0.25, 0.5, 0.75)) AS cost_quartiles, COUNT_IF(status = 'LOST') AS lost_events, STDDEV_SAMP(cost) AS cost_stddev FROM reconciled GROUP BY CASE WHEN cost >= 78 THEN 'PREMIUM' ELSE 'STANDARD' END, DATE_TRUNC('YEAR', delivered_date) HAVING lost_events > 1;
